const rawInput = $input.first().json;
const q = rawInput.query ? rawInput.query : rawInput;

// seller_id is now OPTIONAL. An existing, signed-in seller reconnecting
// from /connect-amazon still passes their real seller_id (unchanged
// behavior - Store OAuth State below writes it straight through). A
// brand-new visitor clicking "Connect Your Amazon Seller Account" on the
// anonymous landing page has no seller_id yet; wf10 resolves who they
// are once Amazon's redirect hands back a selling_partner_id. A null
// stored here is what wf10 reads to know which of those two cases it's
// handling - see wf10's "Check Seller ID Presence" node.
const sellerId = (q.seller_id && String(q.seller_id).trim()) ? String(q.seller_id).trim() : null;

// This IS the actual CSRF/replay defense, not a cosmetic identifier.
// Two prior attempts using actual crypto both failed in this specific
// n8n sandbox: require('crypto') is blocked, and the global `crypto`
// object isn't exposed either. Rather than guess at sandbox internals
// a third time, this uses only fundamental JavaScript with zero
// external dependency - guaranteed available in any JS engine.
// Adequate here specifically because this token is short-lived (10
// minutes), single-use (checked against the database), and not the
// only line of defense - it doesn't need to withstand sophisticated
// cryptanalysis, just prevent casual CSRF/replay in its narrow window.
function randomSegment() {
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}
const state = randomSegment() + '-' + randomSegment() + '-' + randomSegment();

return [{ json: {
  decision: 'VALID',
  seller_id: sellerId,
  state: state
}}];

const prev = $('Validate Input & Generate State').first().json;

// version=beta is required while the app is still in Draft / not yet
// publicly listed - remove this parameter once the app is actually
// listed on the Selling Partner Appstore, or it will authorize the
// wrong (draft) version.
const consentUrl = 'https://sellercentral.amazon.com/apps/authorize/consent'
  + '?application_id=' + encodeURIComponent('amzn1.sp.solution.5e1b73ff-7d0c-4c99-a019-dccd1d314d85')
  + '&state=' + encodeURIComponent(prev.state)
  + '&version=beta';

return [{ json: { redirect_url: consentUrl } }];
